        while queue:
            size = len(queue)
            for _ in range(size):
                current = queue.popleft()
                if a[current - 1] % 2 != a[start - 1] % 2:
                    return steps
                for next_pos in [current - a[current - 1], current + a[current - 1]]:
                    if 1 <= next_pos <= n and not visited[next_pos]:
